-- Хранение картинок ПДД (билеты категории A,B, датасет etspring/pdd_russia)
-- прямо в БД, а не в объектном хранилище Beget S3 — чтобы не гонять трафик
-- через внешний S3-прокси ради статичного одноразового набора картинок,
-- который отдаётся только курьеру/пользователю тамагочи через Edge Function
-- pdd-image (см. supabase/functions/pdd-image).

CREATE TABLE IF NOT EXISTS public.pdd_images (
  id   text PRIMARY KEY,
  mime text NOT NULL DEFAULT 'image/jpeg',
  data bytea NOT NULL
);

CREATE OR REPLACE FUNCTION public.get_pdd_image(image_id text)
RETURNS TABLE(mime text, data_b64 text)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT mime, encode(data, 'base64') FROM public.pdd_images WHERE id = image_id;
$$;

